package net.civeira.phylax.feature.access.userwebauthncredential.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.access.userwebauthncredential.domain.UserWebauthnCredential;
import net.civeira.phylax.feature.access.userwebauthncredential.domain.valueobject.TransportsJsonVO;

class TransportsJsonValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of transports json of user webauthn credential")
  void test_transports_json_value_holder_assign_plain_value() {
    Object holder = new Object();
    TransportsJsonValueHolder<Object> value = new TransportsJsonValueHolder<>(holder);
    Assertions.assertSame(holder, value.transportsJson("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getTransportsJsonValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals("one", value.getTransportsJson().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.transportsJsonNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getTransportsJsonValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getTransportsJson().isPresent(),
        "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of transports json of user webauthn credential")
  void test_transports_json_value_holder_assign_value_object() {
    Object holder = new Object();
    TransportsJsonValueHolder<Object> value = new TransportsJsonValueHolder<>(holder);
    TransportsJsonVO vo = TransportsJsonVO.from("one");
    Assertions.assertFalse(value.getTransportsJsonValue().isPresent(),
        "A new holder must be empty");
    Assertions.assertSame(holder, value.transportsJson(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getTransportsJsonValue().orElseThrow());
    Assertions.assertSame(holder, value.transportsJson(Optional.empty()));
    Assertions.assertFalse(value.getTransportsJsonValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.transportsJson(Optional.of(vo)));
    Assertions.assertSame(vo, value.getTransportsJsonValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of transports json of user webauthn credential against the original")
  void test_transports_json_value_holder_read() {
    Object holder = new Object();
    TransportsJsonValueHolder<Object> value = new TransportsJsonValueHolder<>(holder);
    TransportsJsonVO vo = TransportsJsonVO.from("one");
    TransportsJsonVO other = TransportsJsonVO.from("one");
    UserWebauthnCredential original = Mockito.mock(UserWebauthnCredential.class);
    Mockito.when(original.getTransportsJsonValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readTransportsJson(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readTransportsJson(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.transportsJson(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readTransportsJson(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readTransportsJson(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of transports json of user webauthn credential")
  void test_transports_json_value_holder_unset() {
    Object holder = new Object();
    TransportsJsonValueHolder<Object> value = new TransportsJsonValueHolder<>(holder);
    TransportsJsonVO vo = TransportsJsonVO.from("one");
    value.transportsJson(vo);
    Assertions.assertSame(holder, value.unsetTransportsJsonIfMatches("transportsJson_other"));
    Assertions.assertTrue(value.getTransportsJsonValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetTransportsJsonIfMatches("transportsJson"));
    Assertions.assertFalse(value.getTransportsJsonValue().isPresent(),
        "The field name must clear the value");
    value.transportsJson(vo);
    Assertions.assertSame(holder, value.unsetTransportsJson());
    Assertions.assertFalse(value.getTransportsJsonValue().isPresent(),
        "Unset must clear the value");
  }
}
